sp_widget.client_script:
api.controller = function($scope) {
  var c = this;

  c.goToPrograms = function() {
    window.location.href = '?id=grant_programs';
  };

  c.goToApplication = function() {
    window.location.href = '?id=applicant_form';
  };
}

sp_widget.css:
/* ─── Reset ───────────────────────────────────────────── */
.gatenow-hero-wrapper *,
.gatenow-hero-wrapper *::before,
.gatenow-hero-wrapper *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* ─── Wrapper ─────────────────────────────────────────── */
.gatenow-hero-wrapper {
  font-family: 'Inter', 'Plus Jakarta Sans', 'Segoe UI', sans-serif;
  margin-left: -15px;
  margin-right: -15px;
  width: calc(100% + 30px);
}

/* ─── Hero Section ────────────────────────────────────── */
.gn-hero {
  position: relative;
  width: 100%;
  min-height: 620px;
  height: auto;
  background: linear-gradient(114.089deg, rgb(84, 60, 168) 17.665%, rgb(88, 107, 199) 114.38%);
  display: flex;
  align-items: center;
  overflow: hidden;
  padding: 80px 0;
}

/* ─── Inner Layout ────────────────────────────────────── */
.gn-hero-inner {
  position: relative;
  z-index: 3;
  width: 100%;
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 80px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
}

/* ─── Hero Content (Left) ─────────────────────────────── */
.gn-hero-content {
  position: relative;
  z-index: 3;
  flex: 0 0 auto;
  max-width: 520px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  animation: gnFadeUp 0.7s ease both;
}

/* ─── Dot Grid Container ──────────────────────────────── */
.gn-dots-container {
  position: relative;
  z-index: 2;
  flex: 0 0 auto;
  pointer-events: none;
}

.gn-dot-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: repeat(5, 1fr);
  gap: 28px;
  align-items: center;
  justify-items: center;
}

/* ─── Individual Dots ─────────────────────────────────── */
.gn-dot {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: block;
  background: rgba(255, 255, 255, var(--o, 0.5));
  animation: gnDotFloat 4s ease-in-out infinite;
  animation-delay: var(--d, 0s);
  will-change: transform;
  flex-shrink: 0;
}

/* ─── Badge ───────────────────────────────────────────── */
.gn-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.30);
  color: rgba(255, 255, 255, 0.92);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 6px 14px;
  border-radius: 100px;
  margin-bottom: 22px;
  backdrop-filter: blur(6px);
  animation: gnFadeUp 0.5s ease both;
}

.gn-badge-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #7dd3fc;
  box-shadow: 0 0 8px rgba(125, 211, 252, 0.8);
  flex-shrink: 0;
  animation: gnPulse 2.2s ease-in-out infinite;
}

/* ─── Heading ─────────────────────────────────────────── */
.gn-heading {
  font-family: 'Plus Jakarta Sans', 'Inter', sans-serif;
  font-size: clamp(20px, 2.2vw, 30px);
  font-weight: 700;
  line-height: 1.18;
  color: #ffffff;
  margin-bottom: 18px;
  letter-spacing: -0.02em;
  animation: gnFadeUp 0.65s ease both;
}

/* ─── Subheading ──────────────────────────────────────── */
.gn-subheading {
  font-size: clamp(13px, 1.1vw, 15px);
  font-weight: 400;
  line-height: 1.7;
  color: rgba(255, 255, 255, 0.72);
  max-width: 430px;
  margin-bottom: 36px;
  animation: gnFadeUp 0.75s ease both;
}

/* ─── CTA Buttons ─────────────────────────────────────── */
.gn-btn-group {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  animation: gnFadeUp 0.85s ease both;
}

.gn-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 500;
  padding: 11px 22px;
  border-radius: 8px;
  text-decoration: none !important;
  cursor: pointer;
  transition: all 0.22s ease;
  white-space: nowrap;
  letter-spacing: 0.01em;
  line-height: 1;
}

.gn-btn-solid-white {
  background: #ffffff;
  border: none;
  color: #313131;
}
.gn-btn-solid-white:hover {
  background: #f1f5f9;
  transform: translateY(-1px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
  color: #313131;
}
.gn-btn-solid-white:hover .gn-btn-icon {
  transform: translateX(3px);
}

.gn-btn-outline {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.85);
  color: #ffffff;
  backdrop-filter: blur(6px);
}
.gn-btn-outline:hover {
  background: rgba(255, 255, 255, 0.16);
  transform: translateY(-1px);
  color: #ffffff;
}

.gn-btn-icon {
  transition: transform 0.2s ease;
  flex-shrink: 0;
}

/* ─── Keyframes ───────────────────────────────────────── */
@keyframes gnDotFloat {
  0%   { transform: translate(0px, 0px); }
  25%  { transform: translate(var(--fx, -5px), var(--fy, -6px)) scale(1.04); }
  55%  { transform: translate(calc(var(--fx, -5px) * -0.6), calc(var(--fy, -6px) * -0.7)) scale(0.97); }
  80%  { transform: translate(calc(var(--fx, -5px) * 0.3), calc(var(--fy, -6px) * 0.4)); }
  100% { transform: translate(0px, 0px); }
}

@keyframes gnFadeUp {
  from { opacity: 0; transform: translateY(20px); }
  to   { opacity: 1; transform: translateY(0); }
}

@keyframes gnPulse {
  0%, 100% { transform: scale(1);    opacity: 1; }
  50%       { transform: scale(1.6); opacity: 0.5; }
}

/* ─── Responsive ──────────────────────────────────────── */
@media (min-width: 1400px) {
  .gn-hero-inner { padding: 0 100px; }
  .gn-dot-grid   { gap: 32px; }
  .gn-dot        { width: 42px; height: 42px; }
}

@media (max-width: 1200px) {
  .gn-hero-inner { padding: 0 60px; }
  .gn-dot-grid   { gap: 22px; }
  .gn-dot        { width: 30px; height: 30px; }
}

@media (max-width: 1024px) {
  .gn-hero-inner { padding: 0 40px; }
  .gn-dot-grid   { gap: 18px; }
  .gn-dot        { width: 26px; height: 26px; }
}

@media (max-width: 820px) {
  .gn-hero { padding: 80px 0 60px; }
  .gn-hero-inner {
    padding: 0 32px;
    flex-direction: column;
    align-items: flex-start;
    gap: 48px;
  }
  .gn-hero-content        { max-width: 100%; }
  .gn-dots-container      { align-self: center; opacity: 0.7; }
  .gn-dot-grid            { gap: 14px; }
  .gn-dot                 { width: 22px; height: 22px; }
}

@media (max-width: 520px) {
  .gn-hero       { padding: 72px 0 48px; }
  .gn-hero-inner { padding: 0 24px; }
  .gn-dots-container { display: none; }
  .gn-heading    { font-size: 20px; }
  .gn-subheading { font-size: 13px; }
  .gn-badge      { font-size: 10px; padding: 5px 12px; }
  .gn-btn        { font-size: 12px; padding: 10px 18px; }
}

sp_widget.script:
(function() {

  function optVal(opt, fallback) {
    return (opt && opt !== '') ? opt : fallback;
  }

  data.heading     = optVal(options.heading,     "Unlock Federal Funding for America's Future");
  data.description = optVal(options.description, "GateNow simplifies every step — discover open grants, confirm eligibility, and submit compliant federal applications all in one secure, guided platform.");
  data.badge       = "Federal Grant Management Platform";

  data.programs_page = optVal(options.programs_page, "grant_programs");
  data.apply_page    = optVal(options.apply_page,    "applicant_form");

})();
